// Geographic placement helpers use local metres, not compressed game coordinates.
export function offsetPoint(p,east,north){return {longitude:p.longitude+east/(111320*Math.cos(p.latitude*Math.PI/180)),latitude:p.latitude+north/110574};}
export function rectangle(record){const angle=record.heading*Math.PI/180,f=[Math.sin(angle),Math.cos(angle)],s=[Math.cos(angle),-Math.sin(angle)];return [[-1,-1],[1,-1],[1,1],[-1,1]].map(([x,y])=>offsetPoint(record.point,s[0]*x*record.width/2+f[0]*y*record.length/2,s[1]*x*record.width/2+f[1]*y*record.length/2));}
export function overlaps(a,b){const origin=a.point;const local=p=>[(p.longitude-origin.longitude)*111320*Math.cos(origin.latitude*Math.PI/180),(p.latitude-origin.latitude)*110574];const A=rectangle(a).map(local),B=rectangle(b).map(local);for(const poly of [A,B])for(let i=0;i<4;i++){const j=(i+1)%4,axis=[-(poly[j][1]-poly[i][1]),poly[j][0]-poly[i][0]];const dots=p=>p.map(v=>v[0]*axis[0]+v[1]*axis[1]),da=dots(A),db=dots(B);if(Math.max(...da)<Math.min(...db)||Math.max(...db)<Math.min(...da))return false;}return true;}
export async function createGeoDeployment({view,map,buildings,buildingView,Graphic,GraphicsLayer,Point,getPlace,getSurfaceHeight=()=>0}){
  const models=await fetch('assets/geo-models.json').then(r=>{if(!r.ok)throw Error('車輛模型清單未能讀取');return r.json();});
  const units=[{id:'engine1',name:'第一車組・水箱車',model:'engine',crew:['leader','crew','crew','crew']},{id:'engine2',name:'第二車組・水箱車',model:'engine',crew:['squad','crew','crew','crew']},{id:'engine3',name:'第三車組・水箱車',model:'engine',crew:['squad','crew','crew','crew']},{id:'ambulance',name:'第四車組・救護車',model:'ambulance',crew:['crew','crew']},{id:'aerial',name:'雲梯車・待命',model:'aerial',crew:['crew','crew']},{id:'commander',name:'中隊長',model:'commander',crew:[]}];
  const states={xinyi:{items:{},logs:[],target:null,entrance:null},ximen:{items:{},logs:[],target:null,entrance:null}};
  const groundLayer=new GraphicsLayer({title:'消防部署',elevationInfo:{mode:'relative-to-ground'}}),areaLayer=new GraphicsLayer({title:'雲梯作業預留區',elevationInfo:{mode:'on-the-ground'}}),targetLayer=new GraphicsLayer({title:'搶救目標',elevationInfo:{mode:'absolute-height'}});map.addMany([areaLayer,groundLayer,targetLayer]);
  const panel=document.getElementById('deployment');
  panel.innerHTML='<h2>消防部署試用</h2><p>先點選搶救建物及第一正面入口，再於道路空地放置車組。車輛不會自動行駛。</p><div class="deploy-row"><button data-mode="target">選搶救建物</button><button data-mode="entrance">指定正面入口</button></div><p id="targetInfo">尚未選擇搶救建物。</p><label for="geoUnit">車組／指揮人員</label><select id="geoUnit"></select><label for="geoHeading">車頭朝向（0° 北、90° 東）</label><input id="geoHeading" type="range" min="0" max="355" step="5" value="0"><output id="headingLabel">0°</output><div class="deploy-row"><button data-mode="vehicle">放置／重選車位</button><button data-mode="crew">放置車組人員</button><button id="rotateGeo">套用朝向</button><button id="cancelGeo">取消選點</button><button id="focusGeo">拉近選定車組</button></div><label for="geoTask">部署命令</label><select id="geoTask"><option>待命</option><option>外部偵查</option><option>滅火部署</option><option>供水部署</option><option>救護部署</option><option>搜索準備</option></select><button id="assignGeo">記錄部署命令</button><p id="deployStatus" role="status">請先選擇搶救建物。</p><div id="geoSummary"></div><div class="deploy-row"><button id="removeGeo">移除選定車組</button><button id="exportGeo">下載本區部署紀錄</button></div><details><summary>本版操作範圍</summary><p>可放置原車型及人員、調整車頭方向、標記建物與入口、記錄命令。朝向與第一正面由你依現地判斷。</p><p>碰撞檢查涵蓋車組預留範圍與目前可見建物；不代表道路合法性或作業安全。雲梯維持收梯待命，橙框為模型作業預留區，尚未啟用支腿、升梯、入屋及出水動畫。</p></details><h2>本區指揮紀錄</h2><ol id="geoLogs"></ol>';
  const $=id=>document.getElementById(id),unitSelect=$('geoUnit');for(const u of units){const o=document.createElement('option');o.value=u.id;o.textContent=u.name;unitSelect.append(o);}
  let mode=null,generation=0,busy=false;
  const state=()=>states[getPlace()],unit=()=>units.find(u=>u.id===unitSelect.value),say=t=>{$('deployStatus').textContent=t;};
  function log(message){state().logs.unshift({time:new Date().toISOString(),message});}
  function symbol(key,heading){const m=models[key];return {type:'point-3d',symbolLayers:[{type:'object',resource:{href:new URL(m.file,location.href).href},width:m.width,depth:m.depth,height:m.height,heading:heading+m.headingOffset,anchor:'relative',anchorPosition:{x:0,y:0,z:-.5}}]};}
  function addModel(key,point,heading,title){groundLayer.add(new Graphic({geometry:new Point({...point,z:getSurfaceHeight(point),spatialReference:{wkid:4326}}),symbol:symbol(key,heading),attributes:{title},popupTemplate:{title:'{title}',content:'部署試用・原有模型'}}));}
  function marker(point,title,color,absolute=false){(absolute?targetLayer:groundLayer).add(new Graphic({geometry:new Point({...point,z:absolute?(point.z||0):0,spatialReference:{wkid:4326}}),symbol:{type:'point-3d',symbolLayers:[{type:'icon',size:14,resource:{primitive:'circle'},material:{color},outline:{color:'white',size:1}},{type:'text',text:title,size:12,material:{color:'white'},halo:{color:'#102331',size:1}}],verticalOffset:{screenLength:28,maxWorldLength:30,minWorldLength:3}}}));}
  function paint(){groundLayer.removeAll();areaLayer.removeAll();targetLayer.removeAll();const s=state();if(!s)return;for(const item of Object.values(s.items)){if(item.kind==='crew'){const u=units.find(u=>u.id===item.unitId);u.crew.forEach((key,i)=>{const a=item.heading*Math.PI/180,x=(i%2-.5)*.9,y=(Math.floor(i/2)-.5)*.9;addModel(key,offsetPoint(item.point,x*Math.cos(a)+y*Math.sin(a),-x*Math.sin(a)+y*Math.cos(a)),item.heading,u.name+'人員');});}else{const u=units.find(u=>u.id===item.unitId);addModel(u.model,item.point,item.heading,u.name);if(u.id==='aerial'){const ring=rectangle(item).map(p=>[p.longitude,p.latitude]);ring.push(ring[0]);areaLayer.add(new Graphic({geometry:{type:'polygon',rings:[ring],spatialReference:{wkid:4326}},symbol:{type:'simple-fill',color:[255,170,65,.12],outline:{color:'#ffb34e',width:1.5}}}));}}}if(s.entrance)marker(s.entrance,'第一正面入口','#60d6be');if(s.target)marker(s.target.point,'搶救目標','#ff8b49',true);}
  function refresh(){const s=state(),enabled=!!s;panel.querySelectorAll('button,select,input').forEach(e=>e.disabled=!enabled||busy);$('geoUnit').disabled=!enabled||busy;$('geoSummary').replaceChildren();$('geoLogs').replaceChildren();if(!s){say('請切換至信義或西門，使用部署試用。');$('targetInfo').textContent='富錦街原演練保留於消防訓練頁。';return;}
    $('targetInfo').textContent=s.target?'已選建物 '+s.target.id+(Number.isFinite(s.target.height)?'・資料高度 '+s.target.height.toFixed(1)+' m':'・高度資料未提供')+(s.entrance?'・入口已指定':'・請指定第一正面入口'):'尚未選擇搶救建物。';
    for(const u of units){const item=s.items[u.id],row=document.createElement('p');row.textContent=u.name+'：'+(item?'已配置・'+item.heading+'°・'+(item.task||'待命'):'未配置')+(s.items[u.id+'-crew']?'・人員已配置':'');$('geoSummary').append(row);}
    for(const entry of s.logs.slice(0,25)){const li=document.createElement('li');li.textContent=new Date(entry.time).toLocaleTimeString('zh-TW',{hour12:false})+' '+entry.message;$('geoLogs').append(li);}
    $('focusGeo').disabled=busy||!s.items[unit().id];$('removeGeo').disabled=busy||!s.items[unit().id];$('rotateGeo').disabled=busy||!s.items[unit().id];$('assignGeo').disabled=busy||!s.items[unit().id];panel.querySelector('[data-mode=crew]').disabled=busy||!unit().crew.length||!s.items[unit().id];panel.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));
  }
  function cancel(){generation++;mode=null;view.popupEnabled=true;refresh();}
  panel.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(!state())return;mode=b.dataset.mode;generation++;view.closePopup();view.popupEnabled=false;refresh();say(mode==='target'?'點選地圖上的官方建物。':mode==='entrance'?'點選目標建物第一正面的地面入口位置。':'請先放大到街道，再點選可部署的地面空間。');});
  unitSelect.onchange=()=>{cancel();const item=state()?.items[unit().id];$('geoHeading').value=item?.heading||0;$('headingLabel').textContent=$('geoHeading').value+'°';$('geoTask').value=item?.task||'待命';};$('geoHeading').oninput=()=>{$('headingLabel').textContent=$('geoHeading').value+'°';};$('cancelGeo').onclick=()=>{cancel();say('已取消選點。');};
  const distance=(a,b)=>Math.hypot((a.longitude-b.longitude)*111320*Math.cos(a.latitude*Math.PI/180),(a.latitude-b.latitude)*110574);
  async function free(record,id){if(buildingView.updating)throw Error('建物仍在載入，請稍候再放置。');for(const [key,other] of Object.entries(state().items))if(key!==id&&overlaps(record,other))throw Error('此位置與其他車組或雲梯預留區重疊，請另選位置。');const corners=rectangle(record),samples=[record.point,...corners,...corners.map((p,i)=>({longitude:(p.longitude+corners[(i+1)%4].longitude)/2,latitude:(p.latitude+corners[(i+1)%4].latitude)/2}))];
    const pts=samples.map(p=>new Point({...p,spatialReference:{wkid:4326}}));for(const p of pts){const sample=await map.ground.queryElevation(p);if(!Number.isFinite(sample.geometry.z))throw Error('無法確認地面高程，請稍候。');const screen=view.toScreen(sample.geometry);if(!screen||screen.x<0||screen.y<0||screen.x>view.width||screen.y>view.height)throw Error('請讓完整車位出現在畫面內，再放置。');const hit=await view.hitTest(screen,{include:[buildings]});if(hit.results.some(r=>r.graphic?.layer===buildings))throw Error('車位範圍被建物或視線遮擋，請換位置或轉動視角再試。');}
  }
  async function place(record,id,ticket){await free(record,id);if(ticket!==generation)return;state().items[id]=record;log(unit().name+(record.kind==='crew'?'人員已配置':'已配置／調整')+'，朝向 '+record.heading+'°');cancel();paint();say('已放置。請依道路方向與現場條件確認配置。');}
  view.on('click',async event=>{if(!mode||!state()||busy)return;event.stopPropagation();const ticket=generation,action=mode;busy=true;refresh();try{if(view.scale>6000)throw Error('請先放大到街道附近，再選擇位置。');const hit=await view.hitTest(event,{include:[buildings]});if(ticket!==generation)return;
      if(action==='target'){const found=hit.results.find(r=>r.graphic?.layer===buildings);if(!found)throw Error('請點選一棟官方建物。');const a=found.graphic.attributes||{},p=found.mapPoint;if(!p)throw Error('未取得建物位置。');state().target={id:String(a.OBJECTID??a.objectid??'未提供編號'),height:typeof a.H==='number'?a.H:null,point:{longitude:p.longitude,latitude:p.latitude,z:p.z||0},attributes:a};state().entrance=null;log('指定搶救建物 '+state().target.id);cancel();paint();say('搶救建物已標記，請指定第一正面入口。');return;}
      if(hit.results.some(r=>r.graphic?.layer===buildings))throw Error('此處為建物或視線被遮擋，請選可見地面。');const p=hit.ground?.mapPoint;if(!p)throw Error('未取得地面位置，請稍微改變視角。');const point={longitude:p.longitude,latitude:p.latitude};
      if(action==='entrance'){if(!state().target)throw Error('請先選擇搶救建物。');if(distance(point,state().target.point)>150)throw Error('入口距離選定建物過遠，請重新確認。');state().entrance=point;log('指定第一正面入口');cancel();paint();say('入口已標記，可依此配置車組。');return;}
      if(!state().target||!state().entrance)throw Error('請先選定搶救建物與第一正面入口。');if(distance(point,state().entrance)>250)throw Error('部署位置距離入口超過本版 250 m 操作範圍。');const u=unit(),m=models[u.model],heading=Number($('geoHeading').value),crew=action==='crew',id=u.id+(crew?'-crew':'');const record={kind:crew?'crew':'vehicle',unitId:u.id,point,heading,width:crew?2:u.id==='aerial'?Math.max(m.span+4,7):m.span+.6,length:crew?2:m.length+(u.id==='aerial'?2:1),task:state().items[id]?.task||'待命'};await place(record,id,ticket);
    }catch(error){say(error.message||'配置失敗，請重試。');}finally{busy=false;refresh();}});
  $('rotateGeo').onclick=async()=>{if(!state()?.items[unit().id]||busy)return;const ticket=++generation;busy=true;refresh();try{await place({...state().items[unit().id],heading:Number($('geoHeading').value)},unit().id,ticket);}catch(e){say(e.message);}finally{busy=false;refresh();}};
  $('focusGeo').onclick=async()=>{const item=state()?.items[unit().id];if(!item)return;cancel();try{await view.goTo({target:[item.point.longitude,item.point.latitude],zoom:20,tilt:65});}catch(e){if(e.name!=='AbortError')say('無法拉近車組，請手動縮放。');}};
  $('assignGeo').onclick=()=>{const item=state()?.items[unit().id];if(!item)return;item.task=$('geoTask').value;log(unit().name+'：下達「'+item.task+'」命令（未模擬執行）');say('已記錄命令；此版不會自動執行救援動畫。');refresh();};
  $('removeGeo').onclick=()=>{const u=unit();delete state().items[u.id];delete state().items[u.id+'-crew'];log('移除 '+u.name+' 與所屬人員');cancel();paint();};
  $('exportGeo').onclick=()=>{const data={place:getPlace(),savedAt:new Date().toISOString(),coordinateSystem:'WGS84',buildingSource:buildings.url,buildingYear:2024,mode:'deployment-planning-trial',...state()};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=(getPlace()==='xinyi'?'信義':'西門')+'-真實圖資部署.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  refresh();return {setPresetTarget(data){if(!state()||getPlace()!=="ximen")return;cancel();state().target={id:String(data.objectId),height:data.height,point:{longitude:data.center[0],latitude:data.center[1],z:data.roofElevation},attributes:{OBJECTID:data.objectId,H:data.height,Label:data.label}};state().entrance=null;log("指定搶救建物 "+data.objectId);paint();refresh();say("已指定搶救目標，請指定第一正面入口。");},refreshSurface:paint,changePlace(){generation++;mode=null;view.popupEnabled=true;paint();refresh();if(state())say('本區部署已切換；可選擇搶救建物或調整車組。');}};
}
